-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.check_employee_type_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row jsonb := COALESCE(p_new, p_old);
BEGIN
  -- Reads the request role: the dispatcher runs this as the owner, so
  -- current_user is never an API role.
  IF current_setting('role', true) IN ('anon', 'authenticated') IS NOT TRUE THEN
    RETURN;
  END IF;

  -- Moving a person to another employee type changes their access, so it goes
  -- through writeAccessGrants (audit, claims cache).
  IF p_operation = 'UPDATE'
     AND (p_new->>'employeeTypeId') IS DISTINCT FROM (p_old->>'employeeTypeId') THEN
    RAISE EXCEPTION 'An employee''s type can only be changed by the server'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Adding or removing a person on the Admin type is an Admin's call: without
  -- this, a delete and re-insert would move someone onto it.
  IF p_operation IN ('INSERT', 'DELETE')
     AND EXISTS (
       SELECT 1 FROM "employeeType"
       WHERE id = v_row->>'employeeTypeId'
         AND "companyId" = v_row->>'companyId'
         AND "systemType" = 'Admin'
     )
     -- With no page, access_level is Full only for the company's Admin type.
     AND util.access_level(auth.uid()::text, NULL, v_row->>'companyId', NULL) IS DISTINCT FROM 'Full' THEN
    RAISE EXCEPTION 'Only an Admin can add or remove a person on the Admin type'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
END;
$function$;

